          <button class="dl-dock-button" type="button" data-page-target="舞台" data-active="false" title="舞台"><svg class="dl-dock-icon" viewBox="0 0 24 24"><path d="M8 4h8l2 6-6 10-6-10Z"/><path d="M8 10h8"/></svg><span class="dl-dock-label">舞台</span></button>
          <button class="dl-dock-button" type="button" data-page-target="档案" data-active="false" title="档案"><svg class="dl-dock-icon" viewBox="0 0 24 24"><path d="M4 6h16v14H4z"/><path d="M8 6V4h8v2M8 11h8M8 15h5"/></svg><span class="dl-dock-label">档案</span></button>
          <button class="dl-dock-button" type="button" data-page-target="数据" data-active="false" title="数据"><svg class="dl-dock-icon" viewBox="0 0 24 24"><path d="M5 19V9M12 19V5M19 19v-7"/></svg><span class="dl-dock-label">数据</span></button>
          <button class="dl-dock-button" type="button" data-page-target="人物" data-active="false" title="人物"><svg class="dl-dock-icon" viewBox="0 0 24 24"><path d="M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8Z"/><path d="M4 21a8 8 0 0 1 16 0"/></svg><span class="dl-dock-label">人物</span></button>
          <button class="dl-dock-button" type="button" data-page-target="系统" data-active="false" title="系统"><svg class="dl-dock-icon" viewBox="0 0 24 24"><path d="M12 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6Z"/><path d="M19 12h2M3 12h2M12 3v2M12 19v2M17 7l1.4-1.4M5.6 18.4 7 17M7 7 5.6 5.6M18.4 18.4 17 17"/></svg><span class="dl-dock-label">系统</span></button>
