</div>
<script>
(function () {
  'use strict';

  const 页面列表 = ['概览', '舞台', '档案', '数据', '人物', '系统'];
  const 页面颜色 = {
    '概览': '#00f0ff',
    '舞台': '#7efcff',
    '档案': '#ffd166',
    '数据': '#ff005a',
    '人物': '#9dff8f',
    '系统': '#d8f3ff'
  };
  const 路由颜色 = {
    'battle': '#ff005a',
    'trade': '#ffd166',
    'profession': '#7efcff',
    'teaching': '#9dff8f',
    'routine': '#00f0ff',
    'trial_entry': '#ff8a00',
    'travel': '#87a7ff',
    '未命中': 'rgba(224, 224, 224, 0.66)'
  };
  const 主题列表 = ['深空青', '警戒红', '冷白光', '异相紫'];
  const 字号列表 = ['0.92', '1', '1.08', '1.16'];
  const 密度列表 = ['紧凑', '标准', '宽松'];
  const 主题存储键 = 'lwcs_hanayume_plot_regex_holo_theme_v1';
  const 字号存储键 = 'lwcs_hanayume_plot_regex_holo_font_v1';
  const 密度存储键 = 'lwcs_hanayume_plot_regex_holo_density_v1';
  const 空值正则 = /^(?:无|暂无|none|null|n\/a|无相关偏差记录)$/i;

  function 新建(标签, 类名, 文本) {
    const 节点 = document.createElement(标签);
    if (类名) 节点.className = 类名;
    if (文本 !== undefined && 文本 !== null) 节点.textContent = 文本;
    return 节点;
  }

  function 清空(节点) {
    if (节点) 节点.replaceChildren();
  }

  function 读存储(键, 默认值) {
    try {
      return localStorage.getItem(键) || 默认值;
    } catch (错误) {
      return 默认值;
    }
  }

  function 写存储(键, 值) {
    try {
      localStorage.setItem(键, 值);
    } catch (错误) {
      console.warn('全息芯片设置保存失败', 键, 错误);
    }
  }

  function 取文本(节点) {
    return (节点 && 节点.textContent ? 节点.textContent : '').trim();
  }

  function 是空内容(内容) {
    const 文本 = String(内容 || '').trim();
    return !文本 || 空值正则.test(文本);
  }

  function 切行(内容) {
    return String(内容 || '').split(/\r?\n/).map(function (行) { return 行.trim(); }).filter(Boolean);
  }

  function 找分隔位置(行) {
    const 候选 = [行.indexOf(':'), 行.indexOf('：'), 行.indexOf('=')].filter(function (位置) { return 位置 >= 0; });
    if (!候选.length) return -1;
    return Math.min.apply(null, 候选);
  }

  function 按行键值(内容) {
    return 切行(内容).map(function (行) {
      const 位置 = 找分隔位置(行);
      if (位置 < 0 || 位置 > 26) return { 键: '', 值: 行 };
      return { 键: 行.slice(0, 位置).trim(), 值: 行.slice(位置 + 1).trim() };
    });
  }

  function 取属性(节点, 名称) {
    return (节点 && 节点.getAttribute ? 节点.getAttribute(名称) || '' : '').trim();
  }

  function 解析文档(原文) {
    const 包裹 = '<dl-root>' + 原文 + '</dl-root>';
    const 文档 = new DOMParser().parseFromString(包裹, 'text/xml');
    if (!文档.getElementsByTagName('parsererror').length) return 文档;
    const 修复文本 = 包裹.replace(/&(?!amp;|lt;|gt;|quot;|apos;|#\d+;|#x[0-9a-fA-F]+;)/g, '&amp;');
    return new DOMParser().parseFromString(修复文本, 'text/xml');
  }

  function 取全部(文档, 标签) {
    return Array.from(文档.getElementsByTagName(标签));
  }

  function 取单个文本(文档, 标签) {
    return 取文本(文档.getElementsByTagName(标签)[0]);
  }

  function 取头像字(名称) {
    return Array.from(String(名称 || '？').trim())[0] || '？';
  }

  function 取摘要(内容) {
    const 第一行 = 切行(内容)[0] || '';
    const 位置 = 找分隔位置(第一行);
    const 文本 = 位置 >= 0 && 位置 <= 18 ? 第一行.slice(位置 + 1).trim() : 第一行;
    return 文本.length > 46 ? 文本.slice(0, 46) + '...' : 文本;
  }

  function 生成字段组(内容, 高亮台词) {
    const 组 = 新建('div', 'dl-fields');
    const 项们 = 按行键值(内容);
    if (!项们.length) {
      组.appendChild(新建('div', 'dl-field-value', 内容));
      return 组;
    }
    for (const 项 of 项们) {
      if (!项.键) {
        组.appendChild(新建('div', 'dl-field-value', 项.值));
        continue;
      }
      const 行 = 新建('div', 'dl-field-row');
      行.appendChild(新建('div', 'dl-field-name', 项.键));
      const 值 = 新建('div', 'dl-field-value', 项.值);
      if (高亮台词 && /「[^」]+」|"[^"]+"/.test(项.值)) 值.classList.add('dl-dialogue');
      行.appendChild(值);
      组.appendChild(行);
    }
    return 组;
  }

  function 生成文本块(内容) {
    return 新建('div', 'dl-text-block', 内容);
  }

  function 生成卡片(标题, 内容, 类名, 高亮台词) {
    const 卡片 = 新建('article', 'dl-card ' + (类名 || 'dl-data-card'));
    卡片.appendChild(新建('div', 'dl-card-title', 标题));
    if (内容 instanceof Node) {
      卡片.appendChild(内容);
    } else {
      卡片.appendChild(生成字段组(内容, !!高亮台词));
    }
    return 卡片;
  }

  function 生成长文卡片(标题, 内容, 类名) {
    const 卡片 = 新建('article', 'dl-card dl-collapsible ' + (类名 || 'dl-data-card'));
    卡片.appendChild(新建('div', 'dl-card-title', 标题));
    const 正文 = 新建('div', 'dl-collapsible-body');
    正文.appendChild(生成文本块(内容));
    卡片.appendChild(正文);
    if (String(内容 || '').length > 260) {
      卡片.dataset.collapsed = 'true';
      const 按钮 = 新建('button', 'dl-read-button', '展开');
      按钮.type = 'button';
      按钮.addEventListener('click', function () {
        const 收起 = 卡片.dataset.collapsed === 'true';
        卡片.dataset.collapsed = 收起 ? 'false' : 'true';
        按钮.textContent = 收起 ? '收起' : '展开';
      });
      卡片.appendChild(按钮);
    }
    return 卡片;
  }

  function 生成空态(文本) {
    return 新建('div', 'dl-empty', 文本 || '无信号');
  }

  function 解析路由(文本) {
    if (是空内容(文本) || /未命中/.test(文本)) return '未命中';
    const 匹配 = /模块\s*[：:=]\s*([^\s\n]+)/.exec(文本);
    return 匹配 ? 匹配[1].trim() : '命中';
  }

  function 取路由色(模块) {
    return 路由颜色[模块] || '#ff005a';
  }

  function 取召回数量(文档) {
    const 记忆 = 取单个文本(文档, 'recall');
    const 时间线 = 取单个文本(文档, 'timeline_recall');
    const 偏差 = 取单个文本(文档, '偏差账本召回');
    const 记忆数 = (记忆.match(/AM\d+/g) || []).length;
    const 时间线数 = 是空内容(时间线) ? 0 : 切行(时间线).length;
    const 偏差匹配 = 偏差.match(/DV\d+/g);
    const 偏差数 = 是空内容(偏差) ? 0 : (偏差匹配 ? 偏差匹配.length : 切行(偏差).length);
    return 记忆数 + 时间线数 + 偏差数;
  }

  function 取人物数量(文档) {
    const 名称们 = new Set();
    ['npc_profile', 'npc_inner', 'act', 'npc_track', 'npc_jump'].forEach(function (标签) {
      for (const 节点 of 取全部(文档, 标签)) {
        const 名称 = 取属性(节点, 'name');
        if (名称) 名称们.add(名称);
      }
    });
    return 名称们.size;
  }

  function 分解场景(内容) {
    return String(内容 || '').split(/\s*[|｜]\s*/).map(function (项) { return 项.trim(); }).filter(Boolean).join('\n');
  }

  function 渲染概览(面板, 文档, 统计) {
    const 容器 = 面板.querySelector('[data-role="概览页"]');
    清空(容器);
    let 数量 = 0;
    const 场景 = 取单个文本(文档, 'scene');
    const 路由文本 = 取单个文本(文档, '模块路由');
    if (!是空内容(场景)) {
      容器.appendChild(生成卡片('场景', 分解场景(场景), 'dl-scene-card', false));
      数量 += 1;
    }
    if (!是空内容(路由文本)) {
      容器.appendChild(生成卡片('路由', 路由文本, 'dl-route-card', false));
      数量 += 1;
    }
    const 数据 = 'NPC: ' + 统计.角色数 + '\n记忆: ' + 统计.召回数 + '\n档案: ' + 统计.档案数 + '\n舞台: ' + 统计.舞台数 + '\n数据: ' + 统计.数据数;
    容器.appendChild(生成卡片('状态', 数据, 'dl-data-card', false));
    数量 += 1;
    return 数量;
  }

  function 是舞台子标签(节点) {
    return ['act', 'npc_inner', 'interplay'].includes(String(节点.nodeName || '').toLowerCase());
  }

  function 收集舞台旁白(舞台) {
    const 旁白 = [];
    for (const 子 of Array.from(舞台.childNodes)) {
      if (子.nodeType === Node.TEXT_NODE) {
        const 文本 = 子.textContent.trim();
        if (!是空内容(文本)) {
          for (const 行 of 切行(文本)) {
            const 匹配 = /^interplay\s*[：:=]\s*(.+)$/i.exec(行);
            旁白.push(匹配 ? 匹配[1].trim() : 行);
          }
        }
      }
      if (子.nodeType === Node.ELEMENT_NODE && !是舞台子标签(子)) {
        const 文本 = 取文本(子);
        if (!是空内容(文本)) 旁白.push(文本);
      }
    }
    return 旁白.filter(function (项) { return !是空内容(项); });
  }

  function 渲染舞台(面板, 文档) {
    const 容器 = 面板.querySelector('[data-role="舞台页"]');
    清空(容器);
    let 数量 = 0;
    const 舞台们 = 取全部(文档, 'stage');
    const 渲染行动 = function (节点) {
      const 名称 = 取属性(节点, 'name') || '角色';
      容器.appendChild(生成卡片(名称, 取文本(节点), 'dl-action-card', true));
      数量 += 1;
    };
    if (舞台们.length) {
      for (const 舞台 of 舞台们) {
        for (const 子 of Array.from(舞台.childNodes)) {
          if (子.nodeType !== Node.ELEMENT_NODE) continue;
          const 标签 = 子.nodeName.toLowerCase();
          if (标签 === 'act') 渲染行动(子);
          if (标签 === 'interplay' && !是空内容(取文本(子))) {
            容器.appendChild(生成长文卡片('interplay', 取文本(子), 'dl-action-card'));
            数量 += 1;
          }
        }
        for (const 旁白 of 收集舞台旁白(舞台)) {
          容器.appendChild(生成长文卡片('interplay', 旁白, 'dl-action-card'));
          数量 += 1;
        }
      }
    } else {
      for (const 行动 of 取全部(文档, 'act')) 渲染行动(行动);
    }
    if (!数量) 容器.appendChild(生成空态('无舞台'));
    return 数量;
  }

  function 渲染档案(面板, 文档) {
    const 容器 = 面板.querySelector('[data-role="档案页"]');
    清空(容器);
    let 数量 = 0;
    for (const 节点 of 取全部(文档, 'npc_profile')) {
      const 内容 = 取文本(节点);
      const 名称 = 取属性(节点, 'name') || 'NPC';
      const 卡片 = 新建('article', 'dl-card dl-profile-card');
      卡片.tabIndex = 0;
      卡片.setAttribute('role', 'button');
      卡片.setAttribute('aria-expanded', 'false');
      卡片.dataset.open = 'false';
      const 头 = 新建('div', 'dl-profile-head');
      头.appendChild(新建('div', 'dl-avatar', 取头像字(名称)));
      const 名称列 = 新建('div', '');
      名称列.appendChild(新建('div', 'dl-character-name', 名称));
      const 摘要 = 取摘要(内容);
      if (摘要) 名称列.appendChild(新建('div', 'dl-summary', 摘要));
      头.appendChild(名称列);
      const 详情 = 新建('div', 'dl-profile-detail');
      const 内层 = 新建('div', 'dl-profile-detail-inner');
      内层.appendChild(生成字段组(内容, false));
      详情.appendChild(内层);
      卡片.appendChild(头);
      卡片.appendChild(详情);
      容器.appendChild(卡片);
      数量 += 1;
    }
    if (!数量) 容器.appendChild(生成空态('无档案'));
    return 数量;
  }

  function 分解步骤(内容) {
    const 步骤 = [];
    const 正则 = /(step\s*\d+[^：:\n]*(?:[：:]|）)?|【[^】]+】)/gi;
    let 上次 = 0;
    let 标题 = '';
    let 匹配;
    while ((匹配 = 正则.exec(内容))) {
      const 前文 = 内容.slice(上次, 匹配.index).trim();
      if (前文 || 标题) 步骤.push({ 标题: 标题 || '内容', 内容: 前文 });
      标题 = 匹配[0].trim();
      上次 = 正则.lastIndex;
    }
    const 收尾 = 内容.slice(上次).trim();
    if (收尾 || 标题) 步骤.push({ 标题: 标题 || '内容', 内容: 收尾 });
    if (!步骤.length) return 切行(内容).map(function (行, 序号) { return { 标题: 'step ' + (序号 + 1), 内容: 行 }; });
    return 步骤;
  }

  function 渲染数据(面板, 文档) {
    const 容器 = 面板.querySelector('[data-role="数据页"]');
    清空(容器);
    let 数量 = 0;
    const 路由文本 = 取单个文本(文档, '模块路由');
    if (!是空内容(路由文本)) {
      容器.appendChild(生成卡片('模块路由', 路由文本, 'dl-route-card', false));
      数量 += 1;
    }
    const 步骤源 = [
      ['剧情审查', 取单个文本(文档, '剧情审查')],
      ['dm_plan', 取单个文本(文档, 'dm_plan')],
      ['recall', 取单个文本(文档, 'recall')],
      ['timeline_recall', 取单个文本(文档, 'timeline_recall')],
      ['偏差账本召回', 取单个文本(文档, '偏差账本召回')]
    ];
    for (const 项 of 步骤源) {
      const 标题 = 项[0];
      const 内容 = 项[1];
      if (是空内容(内容)) continue;
      for (const 步骤 of 分解步骤(内容)) {
        容器.appendChild(生成长文卡片(标题 + ' · ' + 步骤.标题, 步骤.内容 || 内容, 'dl-data-card'));
        数量 += 1;
      }
    }
    const 账本源 = [
      ['dm_box', 取单个文本(文档, 'dm_box')],
      ['dm_set', 取单个文本(文档, 'dm_set')]
    ];
    for (const 项 of 账本源) {
      if (是空内容(项[1])) continue;
      容器.appendChild(生成长文卡片(项[0], 项[1], 'dl-data-card'));
      数量 += 1;
    }
    if (!数量) 容器.appendChild(生成空态('无数据'));
    return 数量;
  }

  function 生成折叠项(标题, 内容) {
    const 项 = 新建('section', 'dl-accordion-item');
    项.dataset.open = 'false';
    const 头 = 新建('button', 'dl-accordion-head');
    头.type = 'button';
    头.appendChild(新建('span', '', 标题));
    头.appendChild(新建('span', '', '展开'));
    const 体 = 新建('div', 'dl-accordion-body');
    const 内层 = 新建('div', 'dl-accordion-inner');
    内层.appendChild(生成字段组(内容, false));
    体.appendChild(内层);
    头.addEventListener('click', function () {
      const 打开 = 项.dataset.open === 'true';
      项.dataset.open = 打开 ? 'false' : 'true';
      头.lastChild.textContent = 打开 ? '展开' : '收起';
    });
    项.appendChild(头);
    项.appendChild(体);
    return 项;
  }

  function 渲染人物(面板, 文档) {
    const 容器 = 面板.querySelector('[data-role="人物页"]');
    清空(容器);
    let 数量 = 0;
    for (const 节点 of 取全部(文档, 'npc_inner')) {
      const 名称 = 取属性(节点, 'name') || 'NPC';
      容器.appendChild(生成卡片(名称 + ' · inner', 取文本(节点), 'dl-person-card', false));
      数量 += 1;
    }
    const 已消费 = [];
    for (const 节点 of 取全部(文档, 'npc_track')) {
      const 内容 = 取文本(节点);
      const 名称 = 取属性(节点, 'name') || 'NPC';
      已消费.push(内容);
      容器.appendChild(生成折叠项(名称 + ' · track', 内容));
      数量 += 1;
    }
    for (const 节点 of 取全部(文档, 'npc_jump')) {
      const 内容 = 取文本(节点);
      const 名称 = 取属性(节点, 'name') || 'NPC';
      const 时间 = 取属性(节点, '跃过时间');
      已消费.push(内容);
      容器.appendChild(生成折叠项(名称 + (时间 ? ' · ' + 时间 : '') + ' · jump', 内容));
      数量 += 1;
    }
    let 剩余 = 取单个文本(文档, 'dmtrack').replace(取单个文本(文档, 'scene'), '').trim();
    for (const 内容 of 已消费) 剩余 = 剩余.replace(内容, '').trim();
    if (!是空内容(剩余)) {
      容器.appendChild(生成折叠项('dmtrack', 剩余));
      数量 += 1;
    }
    if (!数量) 容器.appendChild(生成空态('无人物'));
    return 数量;
  }

  function 设置主题(面板, 名称) {
    const 主题 = 主题列表.includes(名称) ? 名称 : 主题列表[0];
    面板.dataset.theme = 主题;
    for (const 按钮 of 面板.querySelectorAll('[data-theme-name]')) {
      按钮.setAttribute('aria-pressed', 按钮.dataset.themeName === 主题 ? 'true' : 'false');
    }
    写存储(主题存储键, 主题);
  }

  function 设置字号(面板, 值) {
    const 字号 = 字号列表.includes(String(值)) ? String(值) : '1';
    面板.style.setProperty('--字号倍率', 字号);
    for (const 按钮 of 面板.querySelectorAll('[data-font-value]')) {
      按钮.setAttribute('aria-pressed', 按钮.dataset.fontValue === 字号 ? 'true' : 'false');
    }
    写存储(字号存储键, 字号);
  }

  function 设置密度(面板, 值) {
    const 密度 = 密度列表.includes(值) ? 值 : '标准';
    面板.dataset.density = 密度;
    for (const 按钮 of 面板.querySelectorAll('[data-density-value]')) {
      按钮.setAttribute('aria-pressed', 按钮.dataset.densityValue === 密度 ? 'true' : 'false');
    }
    写存储(密度存储键, 密度);
  }

  function 设置页面(面板, 名称) {
    const 页面 = 页面列表.includes(名称) ? 名称 : '概览';
    面板.dataset.page = 页面;
    面板.style.setProperty('--当前模块色', 页面颜色[页面] || 页面颜色['概览']);
    for (const 页 of 面板.querySelectorAll('.dl-page')) {
      页.dataset.active = 页.dataset.page === 页面 ? 'true' : 'false';
    }
    for (const 按钮 of 面板.querySelectorAll('[data-page-target]')) {
      按钮.dataset.active = 按钮.dataset.pageTarget === 页面 ? 'true' : 'false';
    }
  }

  function 设置路由(面板, 文本) {
    const 模块 = 解析路由(文本);
    面板.style.setProperty('--路由色', 取路由色(模块));
    const 路由文本 = 面板.querySelector('[data-role="路由文本"]');
    if (路由文本) 路由文本.textContent = 模块;
  }

  function 设置折叠(面板, 折叠) {
    面板.dataset.folded = 折叠 ? 'true' : 'false';
    const 按钮 = 面板.querySelector('[data-action="折叠"]');
    if (按钮) 按钮.setAttribute('aria-expanded', 折叠 ? 'false' : 'true');
  }

  function 切换档案(卡片) {
    const 打开 = 卡片.dataset.open === 'true';
    const 容器 = 卡片.closest('[data-role="档案页"]');
    if (容器) {
      for (const 同级 of 容器.querySelectorAll('.dl-profile-card')) {
        同级.dataset.open = 'false';
        同级.setAttribute('aria-expanded', 'false');
      }
    }
    卡片.dataset.open = 打开 ? 'false' : 'true';
    卡片.setAttribute('aria-expanded', 打开 ? 'false' : 'true');
  }

  function 绑定交互(面板) {
    设置主题(面板, 读存储(主题存储键, 主题列表[0]));
    设置字号(面板, 读存储(字号存储键, '1'));
    设置密度(面板, 读存储(密度存储键, '标准'));
    面板.addEventListener('click', function (事件) {
      const 页面按钮 = 事件.target.closest('[data-page-target]');
      if (页面按钮 && 面板.contains(页面按钮)) {
        设置页面(面板, 页面按钮.dataset.pageTarget);
        return;
      }
      const 主题按钮 = 事件.target.closest('[data-theme-name]');
      if (主题按钮 && 面板.contains(主题按钮)) {
        设置主题(面板, 主题按钮.dataset.themeName);
        return;
      }
      const 字号按钮 = 事件.target.closest('[data-font-value]');
      if (字号按钮 && 面板.contains(字号按钮)) {
        设置字号(面板, 字号按钮.dataset.fontValue);
        return;
      }
      const 密度按钮 = 事件.target.closest('[data-density-value]');
      if (密度按钮 && 面板.contains(密度按钮)) {
        设置密度(面板, 密度按钮.dataset.densityValue);
        return;
      }
      const 折叠按钮 = 事件.target.closest('[data-action="折叠"]');
      if (折叠按钮 && 面板.contains(折叠按钮)) {
        设置折叠(面板, 面板.dataset.folded !== 'true');
        return;
      }
      const 档案卡 = 事件.target.closest('.dl-profile-card');
      if (档案卡 && 面板.contains(档案卡)) 切换档案(档案卡);
    });
    面板.addEventListener('keydown', function (事件) {
      const 档案卡 = 事件.target.closest('.dl-profile-card');
      if (!档案卡 || !面板.contains(档案卡)) return;
      if (事件.key !== 'Enter' && 事件.key !== ' ') return;
      事件.preventDefault();
      切换档案(档案卡);
    });
  }

  function 设置状态(面板, 名称, 数量) {
    const 状态 = 面板.querySelector('[data-role="' + 名称 + '状态"]');
    if (状态) 状态.textContent = 数量 + ' 项';
  }

  function 启动(面板) {
    if (面板.dataset.initialized === 'true') return;
    面板.dataset.initialized = 'true';
    const 原文 = (面板.querySelector('.dl-buffer') || {}).value || '';
    const 文档 = 解析文档(原文);
    绑定交互(面板);
    const 统计 = {
      角色数: 取人物数量(文档),
      召回数: 取召回数量(文档),
      档案数: 取全部(文档, 'npc_profile').length,
      舞台数: 取全部(文档, 'act').length + 取全部(文档, 'interplay').length,
      数据数: 0
    };
    const 数据数 = 渲染数据(面板, 文档);
    统计.数据数 = 数据数;
    const 概览数 = 渲染概览(面板, 文档, 统计);
    const 舞台数 = 渲染舞台(面板, 文档);
    const 档案数 = 渲染档案(面板, 文档);
    const 人物数 = 渲染人物(面板, 文档);
    const 系统数 = 1;
    const 角标映射 = [
      ['NPC角标', 统计.角色数],
      ['召回角标', 统计.召回数],
      ['档案角标', 档案数],
      ['数据角标', 数据数]
    ];
    for (const 项 of 角标映射) {
      const 节点 = 面板.querySelector('[data-role="' + 项[0] + '"]');
      if (节点) 节点.textContent = String(项[1]);
    }
    设置状态(面板, '概览', 概览数);
    设置状态(面板, '舞台', 舞台数);
    设置状态(面板, '档案', 档案数);
    设置状态(面板, '数据', 数据数);
    设置状态(面板, '人物', 人物数);
    设置状态(面板, '系统', 系统数);
    设置路由(面板, 取单个文本(文档, '模块路由'));
    设置页面(面板, '概览');
  }

  for (const 面板 of document.querySelectorAll('.dl-panel')) {
    启动(面板);
  }
})();
</script>
